import{at as e,n as t,rt as n,xt as r}from"./chunks/framework.DIOWbp6D.js";var i=JSON.parse(`{"title":"Kits","description":"","frontmatter":{},"headers":[],"relativePath":"ecosystem/kits.md","filePath":"ecosystem/kits.md"}`),a={name:`ecosystem/kits.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="kits" tabindex="-1">Kits <a class="header-anchor" href="#kits" aria-label="Permalink to “Kits”">​</a></h1><p>A <strong>kit</strong> is a curated environment: a <code>kit.hnl</code> v1 manifest (<code>{ name, description, license, libs }</code>) that assembles <code>lib-*</code> packages into a ready-to-use surface for a domain — CLI apps, HTTP servers, browser interop, testing, or the mlopt research stack. Kits are pure curation: no plugins, no entry glue; each listed package&#39;s own <code>pkg.hnl</code> deps pull its contracts and transitive backends.</p><h2 id="application-kits" tabindex="-1">Application kits <a class="header-anchor" href="#application-kits" aria-label="Permalink to “Application kits”">​</a></h2><table tabindex="0"><thead><tr><th>Kit</th><th>What it assembles</th></tr></thead><tbody><tr><td><a href="https://github.com/handl-lang/kit-cli-app" target="_blank" rel="noreferrer">kit-cli-app</a></td><td>Build CLI applications — argv parsing (<code>mri</code>), stdio, POSIX fs/env/time, child processes, JSON, collections</td></tr><tr><td><a href="https://github.com/handl-lang/kit-web-server" target="_blank" rel="noreferrer">kit-web-server</a></td><td>Serve HTTP from handl — epoll accept loop, HTTP/1.1 codec + routing, TLS, WebSocket, JSON</td></tr><tr><td><a href="https://github.com/handl-lang/kit-test" target="_blank" rel="noreferrer">kit-test</a></td><td>In-language test surface — test/property/benchmark/fuzz/snapshot/assert plus deterministic rand and posix stubs</td></tr><tr><td><a href="https://github.com/handl-lang/kit-pkg" target="_blank" rel="noreferrer">kit-pkg</a></td><td>The package kit — <code>.handl.toml</code> project discovery and dependency wiring</td></tr></tbody></table><h2 id="interop-kits" tabindex="-1">Interop kits <a class="header-anchor" href="#interop-kits" aria-label="Permalink to “Interop kits”">​</a></h2><table tabindex="0"><thead><tr><th>Kit</th><th>What it assembles</th></tr></thead><tbody><tr><td><a href="https://github.com/handl-lang/kit-web-browser-iterop" target="_blank" rel="noreferrer">kit-web-browser-iterop</a></td><td>Browser/client-side JS interop — call/invoke/await into JS, fetch and WebSocket over generated WebIDL bindings, JSON + JS str backend</td></tr><tr><td><a href="https://github.com/handl-lang/kit-web-worker-iterop" target="_blank" rel="noreferrer">kit-web-worker-iterop</a></td><td>Web Worker interop for handl-on-JS — JS call/invoke/await surface plus data plumbing (JSON, serialize port, str-js backend)</td></tr></tbody></table><h2 id="mlopt-kits" tabindex="-1">MLOpt kits <a class="header-anchor" href="#mlopt-kits" aria-label="Permalink to “MLOpt kits”">​</a></h2><p>The <code>mlopt</code> research game (see <a href="/docs/ecosystem/#_10-products">Products</a>) has its own kit family — domain kits that wire tensor, carrier, and discovery machinery:</p><table tabindex="0"><thead><tr><th>Kit</th><th>What it assembles</th></tr></thead><tbody><tr><td><a href="https://github.com/handl-lang/kit-torch" target="_blank" rel="noreferrer">kit-torch</a></td><td>PyTorch integration for the mlopt game</td></tr><tr><td><a href="https://github.com/handl-lang/kit-cuda" target="_blank" rel="noreferrer">kit-cuda</a></td><td>CUDA-graph delivery mechanism for the mlopt game</td></tr><tr><td><a href="https://github.com/handl-lang/kit-carriers" target="_blank" rel="noreferrer">kit-carriers</a></td><td>Semantic carriers — online-softmax monoids</td></tr><tr><td><a href="https://github.com/handl-lang/kit-discovery" target="_blank" rel="noreferrer">kit-discovery</a></td><td>Law-discovery engine — census, proposal, verification</td></tr><tr><td><a href="https://github.com/handl-lang/kit-host-tensor" target="_blank" rel="noreferrer">kit-host-tensor</a></td><td>Host-tensor backend — <code>mlopt_core.ports.Sink</code> over native tensor ops</td></tr></tbody></table><p>Kits are data, so composing one is editing a manifest: pick the libs, let <code>pkg.hnl</code> deps resolve the rest. The kits that bootstrap the toolchain itself ship with the platform layer.</p>`,10)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};